#!/usr/bin/env python3
"""统计 CSV 文件每一列的非空值数量。"""

import argparse
import csv
import sys
from collections import Counter


def count_nonempty(path, encoding="utf-8-sig", null_values=("nan", "na", "none", "null")):
    counter = Counter()
    with open(path, newline="", encoding=encoding) as f:
        reader = csv.reader(f)
        try:
            header = next(reader)
        except StopIteration:
            return header, counter
        columns = [name.strip() or f"column_{i}" for i, name in enumerate(header)]
        for width, name in zip(range(len(columns)), columns):
            counter.setdefault(name, 0)
        for row in reader:
            for i, name in enumerate(columns):
                if i < len(row):
                    value = row[i].strip()
                    if value and value.lower() not in null_values:
                        counter[name] += 1
    return columns, counter


def main():
    parser = argparse.ArgumentParser(description="统计 CSV 每一列的非空值数量")
    parser.add_argument("csv_file", help="CSV 文件路径")
    parser.add_argument("--encoding", default="utf-8-sig", help="文件编码，默认 utf-8-sig")
    args = parser.parse_args()

    try:
        columns, counter = count_nonempty(args.csv_file, encoding=args.encoding)
    except FileNotFoundError:
        sys.exit(f"错误：文件不存在 {args.csv_file}")

    for name in columns:
        print(f"{name}\t{counter[name]}")


if __name__ == "__main__":
    main()

